function projectArtData(p){const h=[...String(p.id)].reduce((a,c)=>(a*33+c.charCodeAt(0))%360,210),h2=(h+65)%360;const title=shopSvgEscape(p.name),cat=shopSvgEscape(p.category);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="760" viewBox="0 0 1000 760"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="hsl(${h} 78% 88%)"/><stop offset=".55" stop-color="hsl(${h2} 76% 84%)"/><stop offset="1" stop-color="#fff5fb"/></linearGradient><filter id="n"><feTurbulence baseFrequency=".025" numOctaves="2" seed="${h%17}"/><feBlend mode="soft-light" in2="SourceGraphic"/></filter></defs><rect width="1000" height="760" rx="46" fill="url(#g)"/><circle cx="850" cy="118" r="170" fill="white" opacity=".35"/><circle cx="120" cy="650" r="230" fill="#fff" opacity=".22"/><path d="M35 580 C230 430 360 720 610 535 S880 410 1030 520" fill="none" stroke="rgba(24,21,41,.18)" stroke-width="18" stroke-linecap="round"/><g filter="url(#n)" opacity=".18"><rect width="1000" height="760"/></g><text x="74" y="100" font-family="Arial,Helvetica,sans-serif" font-size="25" font-weight="800" letter-spacing="5" fill="#4f3d6d">PAST-CHAT DESIGN ARCHIVE</text><text x="74" y="155" font-family="Arial,Helvetica,sans-serif" font-size="20" font-weight="700" fill="#6a5c7e">${cat}</text><foreignObject x="70" y="225" width="860" height="290"><div xmlns="http://www.w3.org/1999/xhtml" style="font-family:Arial,Helvetica,sans-serif;font-weight:900;font-size:68px;line-height:.94;letter-spacing:-3px;color:#181529;overflow-wrap:anywhere">${title}</div></foreignObject><text x="74" y="688" font-family="Arial,Helvetica,sans-serif" font-size="25" font-weight="800" fill="#181529">BERRY VIBES STUDIO ✦ ARCHIVE RECORD</text></svg>`;return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)}
