function baseCalories(r){return Math.round(r?.nutrition?.calories??r?.calories??estimateCalories(r||{}))}
function estimateCalories(r){const t=((r.name||'')+' '+(r.group||'')).toLowerCase();let c=260;if(/drink|coffee|tea|latte/.test(t))c=95;if(/dip|sauce|frosting/.test(t))c=150;if(/cookie|donut|brownie|cake|muffin/.test(t))c=230;if(/sandwich|philly|pizza|burrito|quesadilla|pasta/.test(t))c=430;if(/egg|breakfast/.test(t))c=280;if(/snack|side/.test(t))c=200;return c}
function autoNutrition(r){if(r.nutrition){return {calories:Math.round(r.nutrition.calories??baseCalories(r)),protein:+(r.nutrition.protein??0),carbs:+(r.nutrition.carbs??0),fat:+(r.nutrition.fat??0),fiber:+(r.nutrition.fiber??0),exact:true}}const c=baseCalories(r),t=((r.name||'')+' '+(r.group||'')+' '+(r.ingredients||[]).join(' ')).toLowerCase();let p=.18,carb=.50,f=.32,fiber=Math.max(2,Math.round(c/115));if(/chicken|steak|egg|yogurt|cottage|turkey/.test(t)){p=.28;carb=.39;f=.33}if(/coffee|tea|drink|latte/.test(t)){p=.16;carb=.60;f=.24;fiber=Math.max(1,Math.round(c/120))}if(/brownie|cake|cookie|donut|chocolate/.test(t)){p=.11;carb=.56;f=.33}if(/wrap|burrito|pizza|pasta|sandwich|philly/.test(t)){p=.24;carb=.44;f=.32}return {calories:c,protein:Math.round(c*p/4),carbs:Math.round(c*carb/4),fat:Math.round(c*f/9),fiber,exact:false}}
function recipeImage(r){const t=((r.name||'')+' '+(r.group||'')).toLowerCase();if(/coffee|tea|drink|latte|mocha/.test(t))return imageMap.coffee;if(/donut/.test(t))return imageMap.donut;if(/chocolate|brownie|cake|cookie/.test(t))return imageMap.chocolate;if(/sandwich|philly|bagel|toast/.test(t))return imageMap.sandwich;if(/bowl|salad/.test(t))return imageMap.bowl;if(/savory|pizza|pasta|wrap|burrito|egg|chicken/.test(t))return imageMap.savory;return imageMap.sweet}
function tasteText(r){if(r.taste)return r.taste;const t=(r.name||'').toLowerCase();if(/chocolate|brownie|lava/.test(t))return'RICH, CHOCOLATEY AND COZY — EXPECT A SOFT, DESSERT-STYLE BITE.';if(/cinnamon|pancake|french toast/.test(t))return'WARM, CINNAMONNY AND BREAKFAST-COZY — SOFT, SWEET-LEANING AND COMFORTING.';if(/philly|steak|sandwich|bagel/.test(t))return'SAVORY, TOASTY AND SATISFYING — EXPECT MELTY, JUICY COMFORT-FOOD ENERGY.';if(/coffee|tea|latte/.test(t))return'SMOOTH, AROMATIC AND SIP-ABLE — EXPECT A COZY CAFÉ VIBE.';return'SOFT, COZY AND PLAYFUL — EXPECT A REPEATABLE CCD COMFORT-FOOD MOMENT.'}
function recipeFacts(r){const n=autoNutrition(r);return [`🔥 ${n.calories} KCAL PER SAVED SERVING ${n.exact?'IN THE RECORDED CARD.':'AS AN AUTO CCD ARCHIVE ESTIMATE.'}`,`💪🏽 ${Math.round(n.protein)}G PROTEIN · 🌾 ${Math.round(n.fiber)}G FIBER IN THE CURRENT CARD.`,`😋 ${tasteText(r)}`]}
function scaleNut(n,m=1){return {calories:Math.round(n.calories*m),protein:Math.round(n.protein*m*10)/10,carbs:Math.round(n.carbs*m*10)/10,fat:Math.round(n.fat*m*10)/10,fiber:Math.round(n.fiber*m*10)/10}}
function bar(label,v,max,suffix='G'){const p=Math.max(0,Math.min(100,v/max*100));return `<div class="bar-row"><b>${esc(label)}</b><div class="bar-track"><span class="bar-fill" style="width:${p}%"></span></div><strong>${Math.round(v)}${suffix}</strong></div>`}
function totals(){const food=state.logs.filter(x=>x.type==='food'),moves=state.logs.filter(x=>x.type==='move');const s=food.reduce((a,x)=>{const n=x.nutrition||{};a.calories+=+n.calories||0;a.protein+=+n.protein||0;a.carbs+=+n.carbs||0;a.fat+=+n.fat||0;a.fiber+=+n.fiber||0;return a},{calories:0,protein:0,carbs:0,fat:0,fiber:0});return {...s,burn:moves.reduce((a,x)=>a+(+x.burn||0),0)}}
