function initLogin(){if(session()){location.href='index.html';return}const si=$('#signInForm'),su=$('#signUpForm'),sit=$('#signInTab'),sut=$('#signUpTab');function mode(signup){sit.classList.toggle('active',!signup);sut.classList.toggle('active',signup);si.hidden=signup;su.hidden=!signup;si.classList.toggle('hidden',signup);su.classList.toggle('hidden',!signup)}sit.onclick=()=>mode(false);sut.onclick=()=>mode(true);su.onsubmit=e=>{e.preventDefault();const email=$('#signUpEmail').value.trim().toLowerCase(),name=$('#signUpName').value.trim(),pass=$('#signUpPassword').value;if(pass.length<6)return toast('USE 6+ CHARACTERS');const a=accounts();if(a[email])return toast('THAT LOCAL PROFILE ALREADY EXISTS');a[email]={name,hash:hashLite(pass)};localStorage.setItem(AUTH_KEY,JSON.stringify(a));localStorage.setItem(SESSION_KEY,email);state=structuredClone(DEFAULT_STATE);state.profile.name=name;save();location.href='index.html'};si.onsubmit=e=>{e.preventDefault();const email=$('#signInEmail').value.trim().toLowerCase(),pass=$('#signInPassword').value,a=accounts();if(!a[email]||a[email].hash!==hashLite(pass))return toast('EMAIL OR PASSWORD DOES NOT MATCH');localStorage.setItem(SESSION_KEY,email);location.href='index.html'}}
function initDashboard(){const t=totals();$('#todayDate').textContent=new Date().toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'}).toUpperCase();$('#todayTime').textContent=new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});$('#dashboardStats').innerHTML=[['🍽️','FOOD',Math.round(t.calories)+' KCAL'],['💪🏽','PROTEIN',Math.round(t.protein)+'G'],['🌾','FIBER',Math.round(t.fiber)+'G'],['💧','WATER',Math.round(state.water)+' OZ'],['🚶🏽‍♀️','MOVE BURN',t.burn+' KCAL']].map(x=>`<div class="stat-card"><span>${x[0]} ${x[1]}</span><strong>${x[2]}</strong></div>`).join('');$('#macroBars').innerHTML=[bar('CARBS',t.carbs,250),bar('PROTEIN',t.protein,100),bar('FAT',t.fat,80),bar('FIBER',t.fiber,30)];const remLo=Math.max(0,2100-t.calories),remHi=Math.max(0,2150-t.calories);$('#maintenanceText').textContent=t.calories?`${Math.round(t.calories)} KCAL LOGGED · ${Math.round(remLo)}–${Math.round(remHi)} KCAL TO THE 2,100–2,150 REFERENCE`:'NO FOOD LOGGED YET · 2,100–2,150 KCAL REFERENCE';$('#maintenanceFill').style.width=Math.min(100,t.calories/2150*100)+'%';const tags={'GRAINS + BASE':0,'PROTEIN':0,'FRUIT + VEG':0,'FUN + EXTRAS':0};state.logs.filter(x=>x.type==='food').forEach(x=>{const s=(x.name||'').toLowerCase();if(/bread|bagel|pancake|oat|flour|rice|pasta|tortilla|pizza|cracker/.test(s))tags['GRAINS + BASE']++;if(/egg|chicken|steak|yogurt|cheese|milk|cottage|protein/.test(s))tags.PROTEIN++;if(/apple|berry|veggie|spinach|pumpkin|orange|avocado/.test(s))tags['FRUIT + VEG']++;if(/chocolate|cookie|cake|donut|dip|sauce|candy|ice cream/.test(s))tags['FUN + EXTRAS']++});const mx=Math.max(1,...Object.values(tags));$('#pyramidBars').innerHTML=Object.entries(tags).map(([k,v])=>bar(k,v,mx,'×')).join('');renderLog($('#recentLogs'));$('#clearToday').onclick=()=>{if(confirm('CLEAR TODAY\'S LOCAL FOOD, MOVEMENT + WATER LOGS?')){state.logs=[];state.water=0;save();initDashboard()}}}
function groupsTo(select,arr){if(!select)return;const g=[...new Set(arr.map(r=>r.group).filter(Boolean))].sort();select.innerHTML='<option value="all">ALL WORLDS</option>'+g.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}
