function initFoods(){groupsTo($('#foodGroup'),allRecipes());function render(){const q=$('#foodSearch').value.toLowerCase(),g=$('#foodGroup').value;const a=allRecipes().filter(r=>(g==='all'||r.group===g)&&((r.name+' '+r.group).toLowerCase().includes(q)));$('#foodGrid').innerHTML=a.slice(0,foodVisible).map(foodCard).join('');$$('[data-food-open]').forEach(b=>b.onclick=()=>openFood(b.dataset.foodOpen));$('#loadMoreFood').hidden=foodVisible>=a.length}$('#foodSearch').oninput=()=>{foodVisible=18;render()};$('#foodGroup').onchange=()=>{foodVisible=18;render()};$('#loadMoreFood').onclick=()=>{foodVisible+=18;render()};render();$('#sotdGrid').innerHTML=SOTD_ITEMS.map((s,i)=>{const qs=[];for(let q=s.min;q<=s.max+1e-9;q+=s.step)qs.push(q);return `<article class="sotd-card" style="background-image:url('${s.image}')"><span>${s.emoji} ${esc(s.unit)}</span><h3>${esc(s.name)}</h3><p>${esc(s.note)}</p><div class="portion-buttons">${qs.map(q=>`<button data-sotd="${i}" data-sotd-qty="${q}">LOG ${q} · ${Math.round(s.calories*q)} KCAL</button>`).join('')}</div></article>`}).join('');$$('[data-sotd]').forEach(b=>b.onclick=()=>{const s=SOTD_ITEMS[+b.dataset.sotd],qty=+b.dataset.sotdQty,c=s.calories*qty,n={calories:Math.round(c),carbs:Math.round(c*.58/4),protein:Math.max(1,Math.round(c*.07/4)),fat:Math.round(c*.35/9),fiber:Math.max(0,Math.round(c/180))};addFood('SOTD · '+s.name,n,(s.recorded?'RECORDED CALORIE · ':'AUTO CCD ESTIMATE · ')+qty+' '+s.unit+(qty===1?'':'S'))});function water(){ $('#waterTotal').textContent=Math.round(state.water)+' OZ';$('#waterOrb').innerHTML=`<b>${Math.round(state.water)}</b><span>OZ</span>`}$$('[data-water]').forEach(b=>b.onclick=()=>{state.water=Math.round((state.water+(+b.dataset.water))*10)/10;save();water();toast('WATER LOGGED NOW 💧')});water()}
function openFood(id){const r=allRecipes().find(x=>x.id===id);if(!r)return;const n=autoNutrition(r),d=$('#foodDialog');$('#foodDialogBody').innerHTML=`<div class="dialog-inner"><div class="dialog-hero"><img src="${recipeImage(r)}" alt="Food photography representing ${esc(r.name)}"><div><span class="mini-kicker">${esc(r.group)}</span><h2>${esc(r.name)}</h2><div class="macro-chips"><span>${n.calories} KCAL</span><span>${Math.round(n.carbs)}G C</span><span>${Math.round(n.protein)}G P</span><span>${Math.round(n.fat)}G FAT</span><span>${Math.round(n.fiber)}G FIBER</span></div><label class="field">SERVING MULTIPLIER<input id="foodMult" type="range" min=".25" max="3" step=".25" value="1"><output id="foodMultOut">1×</output></label><div class="nutrition-ribbon" id="foodScaled"></div><button class="primary-button wide" id="foodLogNow">LOG AT CURRENT TIME ✦</button></div></div><div class="what-expect"><h3>WHAT TO EXPECT / WHAT IT TASTES LIKE</h3><p>${esc(tasteText(r))}</p></div></div>`;function update(){const m=+$('#foodMult').value,s=scaleNut(n,m);$('#foodMultOut').textContent=m+'×';$('#foodScaled').innerHTML=nutRibbon(s)}$('#foodMult').oninput=update;$('#foodLogNow').onclick=()=>{addFood(r.name,scaleNut(n,+$('#foodMult').value),`${+$('#foodMult').value}× SERVING · ${n.exact?'RECORDED/CALCULATED':'AUTO CCD ESTIMATE'}`);d.close()};update();d.showModal()}
