function initMovement(){const g=$('#movementGrid');g.innerHTML=MOVEMENTS.map(m=>`<article class="movement-card ${m.id===currentMove?'active':''}" data-move="${m.id}"><span>${m.emoji}</span><h3>${m.name}</h3><p>${m.copy}</p></article>`).join('');$$('[data-move]').forEach(c=>c.onclick=()=>{currentMove=c.dataset.move;initMovementChoice();$$('[data-move]').forEach(x=>x.classList.toggle('active',x.dataset.move===currentMove))});$('#durationGrid').innerHTML=[10,15,20,30,45,60].map(x=>`<button data-duration="${x}" class="${x===currentDuration?'active':''}">${x} MIN</button>`).join('');$$('[data-duration]').forEach(b=>b.onclick=()=>{currentDuration=+b.dataset.duration;$$('[data-duration]').forEach(x=>x.classList.toggle('active',+x.dataset.duration===currentDuration));initMovementChoice()});$('#logMovement').onclick=()=>{const m=MOVEMENTS.find(x=>x.id===currentMove),burn=movementBurn();state.logs.push({type:'move',emoji:m.emoji,name:m.name,detail:`${currentDuration} MIN · PRESET DURATION · AUTO CLICK TIME`,burn,at:Date.now()});save();toast('MOVEMENT LOGGED NOW '+m.emoji);renderLog($('#movementLog'),x=>x.type==='move')};renderLog($('#movementLog'),x=>x.type==='move');initMovementChoice()}
function movementBurn(){const m=MOVEMENTS.find(x=>x.id===currentMove),lb=+state.profile.weight||118,kg=lb*.453592;return Math.round(m.met*3.5*kg/200*currentDuration)}
function initMovementChoice(){const m=MOVEMENTS.find(x=>x.id===currentMove),burn=movementBurn();$('#moveChoice').textContent=m.name+' · '+currentDuration+' MIN';$('#burnEstimate').textContent=burn+' KCAL';$('#movementFacts').innerHTML=[`${m.emoji} ${m.copy}`,`⏱️ ${currentDuration} MIN IS A BUTTON PRESET — NO DURATION TYPING.`,`✨ ${burn} KCAL IS A MET-STYLE ESTIMATE AND STAYS SEPARATE FROM FOOD CALORIES.`].map(x=>`<div>${x}</div>`).join('')}
function initFasting(){let selected='16:8';$('#fastGrid').innerHTML=FAST_PRESETS.map(f=>`<button data-fast="${f.id}" class="${f.id===selected?'active':''}">${f.id}<span>${f.hours}H FAST</span></button>`).join('');$$('[data-fast]').forEach(b=>b.onclick=()=>{selected=b.dataset.fast;$$('[data-fast]').forEach(x=>x.classList.toggle('active',x.dataset.fast===selected));$('#fastSelected').textContent=selected+' SELECTED'});$('#startFast').onclick=()=>{const f=FAST_PRESETS.find(x=>x.id===selected);state.fast={style:f.id,hours:f.hours,start:Date.now()};save();renderFast();toast('FAST START TIME SAVED NOW ⏳')};$('#breakFast').onclick=()=>{if(!state.fast)return toast('START A FAST FIRST');const done={...state.fast,end:Date.now()};state.fastHistory.push(done);state.fast=null;save();renderFast();toast('FAST BREAK TIME SAVED NOW ✨')};renderFast()}
function renderFast(){const f=state.fast;if(f){const mins=Math.max(0,(Date.now()-f.start)/60000),pct=Math.min(100,mins/(f.hours*60)*100);$('#fastRing').style.setProperty('--fast-progress',pct+'%');$('#fastStatusTitle').textContent=f.style+' · ACTIVE';$('#fastStatusText').textContent=`STARTED ${new Date(f.start).toLocaleString()} · ABOUT ${Math.floor(mins/60)}H ${Math.floor(mins%60)}M ELAPSED.`}else{$('#fastRing').style.setProperty('--fast-progress','0%');$('#fastStatusTitle').textContent='NOT STARTED';$('#fastStatusText').textContent='CHOOSE A PRESET AND TAP START FAST NOW.'}const el=$('#fastHistory');const a=[...state.fastHistory].reverse().slice(0,12);el.innerHTML=a.length?a.map(x=>`<div class="log-entry"><span>⏳</span><div><b>${esc(x.style)} FAST</b><small>${new Date(x.start).toLocaleString()} → ${new Date(x.end).toLocaleString()}</small></div><strong>${((x.end-x.start)/3600000).toFixed(1)}H</strong></div>`).join(''):'<div class="empty">COMPLETED FASTS WILL APPEAR HERE.</div>'}
function manualRestaurantEntry(logNow=false){const restaurant=$('#manualRestaurantName')?.value.trim(),name=$('#manualRestaurantItem')?.value.trim();const raw={restaurant,name,calories:+($('#manualCalories')?.value),carbs:+($('#manualCarbs')?.value),protein:+($('#manualProtein')?.value),fat:+($('#manualFat')?.value),fiber:+($('#manualFiber')?.value||0),servingUnit:$('#manualServing')?.value.trim(),source:'MANUAL RESTAURANT ENTRY',verified:false};if(!restaurant||!name)return toast('ADD THE RESTAURANT + ITEM');if(!['calories','carbs','protein','fat','fiber'].every(k=>Number.isFinite(raw[k])&&raw[k]>=0))return toast('ADD VALID CALORIES + ALL MACROS');const clean=cleanRestaurantNutrition(raw);saveRestaurantToVault(clean);if(logNow)addFood(`${clean.restaurant} · ${clean.name}`,clean,'MANUAL RESTAURANT CARD · AUTO CLICK TIME');['manualRestaurantName','manualRestaurantItem','manualCalories','manualCarbs','manualProtein','manualFat','manualServing'].forEach(id=>{const el=$('#'+id);if(el)el.value=''});if($('#manualFiber'))$('#manualFiber').value='0';toast(logNow?'SAVED + LOGGED NOW 🍟':'SAVED TO RESTAURANT VAULT 💖')}
function initRestaurants(){renderRestaurantTabs();renderPersonalRestaurantVault();$('#lookupRestaurant').onclick=lookupRestaurant;$('#clearRestaurantSearch')?.addEventListener('click',()=>{$('#customRestaurant').value='';$('#customRestaurantItem').value='';$('#lookupResult').innerHTML='THE LOCAL VAULT IS CHECKED FIRST. UNKNOWN ITEMS USE YOUR SECURE NUTRITION ENDPOINT — THE SITE WILL NOT INVENT “EXACT” NUMBERS.'});$('#saveManualRestaurant')?.addEventListener('click',()=>manualRestaurantEntry(false));$('#saveAndLogManualRestaurant')?.addEventListener('click',()=>manualRestaurantEntry(true))}
function renderRestaurantTabs(){const t=$('#restaurantTabs');t.innerHTML=RESTAURANT_CHAINS.map((c,i)=>`<button data-chain="${i}" class="${i===currentRestaurant?'active':''}">${esc(c.name)}</button>`).join('');$$('[data-chain]').forEach(b=>b.onclick=()=>{currentRestaurant=+b.dataset.chain;renderRestaurantTabs()});const c=RESTAURANT_CHAINS[currentRestaurant];$('#restaurantItems').innerHTML=c.items.map((i,idx)=>`<article class="restaurant-card"><img src="${c.image}" alt="Restaurant food photography representing ${esc(c.name)}"><div class="card-body"><span class="mini-kicker">${esc(c.name)}</span><h3>${esc(i.name)}</h3><div class="macro-chips"><span>${i.calories} KCAL</span><span>${i.protein}G P</span><span>${i.fiber}G FIBER</span></div><button class="primary-button" data-rest-item="${idx}">LOG / PORTION ✦</button></div></article>`).join('');$$('[data-rest-item]').forEach(b=>b.onclick=()=>openRestaurant(currentRestaurant,+b.dataset.restItem))}
function openRestaurant(ci,ii){const c=RESTAURANT_CHAINS[ci],i=c.items[ii],d=$('#restaurantDialog');$('#restaurantDialogBody').innerHTML=`<div class="dialog-inner"><div class="dialog-hero"><img src="${c.image}" alt="Restaurant food photography"><div><span class="mini-kicker">${esc(c.name)}</span><h2>${esc(i.name)}</h2><p>${esc(c.source||'SAVED RESTAURANT VAULT')}</p><div class="nutrition-ribbon" id="restNut"></div><div class="portion-buttons">${[.25,.5,.75,1,1.25,1.5].map(x=>`<button data-rest-portion="${x}">${x}×</button>`).join('')}</div><button class="primary-button wide" id="logRest">LOG 1× NOW</button></div></div></div>`;let portion=1;function up(){const n=scaleNut(i,portion);$('#restNut').innerHTML=nutRibbon(n);$('#logRest').textContent=`LOG ${portion}× NOW · ${n.calories} KCAL`}$$('[data-rest-portion]').forEach(b=>b.onclick=()=>{portion=+b.dataset.restPortion;up()});$('#logRest').onclick=()=>{addFood(`${c.name} · ${i.name}`,scaleNut(i,portion),`${portion}× SAVED RESTAURANT PORTION`);d.close()};up();d.showModal()}
function normalizeRestaurantText(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function restaurantVaultId(restaurant,name){return `${normalizeRestaurantText(restaurant)}::${normalizeRestaurantText(name)}`}
function cleanRestaurantNutrition(data,fallbackRestaurant='',fallbackName=''){const n={restaurant:String(data?.restaurant||data?.brand||fallbackRestaurant||'RESTAURANT').trim(),name:String(data?.name||data?.item||data?.food_name||fallbackName||'MENU ITEM').trim(),calories:+data?.calories,carbs:+data?.carbs,protein:+data?.protein,fat:+data?.fat,fiber:+data?.fiber,servingQuantity:data?.servingQuantity??data?.serving_qty??null,servingUnit:data?.servingUnit??data?.serving_unit??'',source:String(data?.source||'CONNECTED NUTRITION ENDPOINT').trim(),verified:data?.verified!==false};if(!['calories','carbs','protein','fat','fiber'].every(k=>Number.isFinite(n[k])))return null;n.id=restaurantVaultId(n.restaurant,n.name);return n}
function findBuiltInRestaurant(restaurant,item){const rn=normalizeRestaurantText(restaurant),it=normalizeRestaurantText(item);for(const c of RESTAURANT_CHAINS){const cn=normalizeRestaurantText(c.name);if(cn.includes(rn)||rn.includes(cn)){const found=c.items.find(x=>{const xn=normalizeRestaurantText(x.name);return xn.includes(it)||it.includes(xn)});if(found)return {restaurant:c.name,name:found.name,calories:+found.calories,carbs:+found.carbs,protein:+found.protein,fat:+found.fat,fiber:+found.fiber,source:c.source||'BUILT-IN RESTAURANT VAULT',verified:found.verified!==false,builtIn:true,image:c.image}}}return null}
function findPersonalRestaurant(restaurant,item){const rn=normalizeRestaurantText(restaurant),it=normalizeRestaurantText(item);return state.restaurantVault.find(x=>{const r=normalizeRestaurantText(x.restaurant),n=normalizeRestaurantText(x.name);return (r.includes(rn)||rn.includes(r))&&(n.includes(it)||it.includes(n))})||null}
function saveRestaurantToVault(data){const clean=cleanRestaurantNutrition(data);if(!clean)return toast('COULD NOT SAVE THAT NUTRITION RESULT');const idx=state.restaurantVault.findIndex(x=>x.id===clean.id);const saved={...clean,savedAt:Date.now()};if(idx>=0)state.restaurantVault[idx]=saved;else state.restaurantVault.unshift(saved);save();renderPersonalRestaurantVault();toast(idx>=0?'SAVED FOOD UPDATED 💖':'SAVED TO MY RESTAURANT VAULT 💖')}
function removeRestaurantFromVault(id){state.restaurantVault=state.restaurantVault.filter(x=>x.id!==id);save();renderPersonalRestaurantVault();toast('REMOVED FROM MY RESTAURANT VAULT')}
function renderPersonalRestaurantVault(){const box=$('#personalRestaurantVault');if(!box)return;const items=state.restaurantVault;box.innerHTML=items.length?items.map(x=>`<article class="personal-vault-card"><div class="personal-vault-emoji">🍔</div><div><span class="mini-kicker">${esc(x.restaurant)}</span><h3>${esc(x.name)}</h3><div class="macro-chips"><span>${Math.round(x.calories)} KCAL</span><span>${Math.round(x.protein)}G P</span><span>${Math.round(x.fiber)}G FIBER</span></div><small>${esc(x.source||'SAVED LOOKUP')}</small></div><div class="personal-vault-actions"><button class="primary-button" data-vault-log="${esc(x.id)}">LOG NOW</button><button class="ghost-button" data-vault-delete="${esc(x.id)}">REMOVE</button></div></article>`).join(''):'<div class="empty">NO CUSTOM RESTAURANT FOODS SAVED YET. SEARCH A NEW ITEM, THEN TAP “SAVE TO MY VAULT.” ✨</div>';$$('[data-vault-log]').forEach(b=>b.onclick=()=>{const x=state.restaurantVault.find(v=>v.id===b.dataset.vaultLog);if(x)addFood(`${x.restaurant} · ${x.name}`,x,'MY SAVED RESTAURANT VAULT')});$$('[data-vault-delete]').forEach(b=>b.onclick=()=>removeRestaurantFromVault(b.dataset.vaultDelete))}
function lookupSourceBadge(data){if(data.builtIn)return'✅ BUILT-IN VERIFIED VAULT';if(data.personal)return'💖 MY SAVED RESTAURANT VAULT';return data.verified?'🌐 CONNECTED NUTRITION RESULT':'⚠️ CONNECTED NUTRITION ESTIMATE'}
function renderRestaurantLookup(data,{canSave=false,personal=false}={}){const clean=cleanRestaurantNutrition(data,data.restaurant,data.name);if(!clean)return;clean.personal=personal;const serving=[clean.servingQuantity,clean.servingUnit].filter(Boolean).join(' ');$('#lookupResult').innerHTML=`<div class="lookup-card"><div class="lookup-title"><div><span class="mini-kicker">${lookupSourceBadge({...data,personal})}</span><h3>${esc(clean.restaurant)} · ${esc(clean.name)}</h3><p>${serving?`SERVING: ${esc(serving)} · `:''}${esc(clean.source)}</p></div><span class="lookup-check">${data.builtIn?'🏪':personal?'💖':'✨'}</span></div><div class="nutrition-ribbon">${nutRibbon(clean)}</div><div class="lookup-actions"><button class="primary-button" id="logLookup">LOG NOW · ${Math.round(clean.calories)} KCAL</button>${canSave?'<button class="ghost-button" id="saveLookup">💖 SAVE TO MY VAULT</button>':''}</div></div>`;$('#logLookup').onclick=()=>addFood(`${clean.restaurant} · ${clean.name}`,clean,personal?'MY SAVED RESTAURANT VAULT':data.builtIn?'BUILT-IN RESTAURANT VAULT':'CONNECTED NUTRITION LOOKUP');if(canSave)$('#saveLookup').onclick=()=>saveRestaurantToVault(clean)}
async function lookupRestaurant(){const rn=$('#customRestaurant').value.trim(),item=$('#customRestaurantItem').value.trim();if(!rn||!item)return toast('ENTER A RESTAURANT + MENU ITEM');const built=findBuiltInRestaurant(rn,item);if(built){renderRestaurantLookup(built);return}const mine=findPersonalRestaurant(rn,item);if(mine){renderRestaurantLookup({...mine,personal:true},{personal:true});return}const endpoint=String(window.BERRY_RESTAURANT_ENDPOINT||'').trim();if(!endpoint){$('#lookupResult').innerHTML='⚠️ NOT IN THE BUILT-IN OR PERSONAL VAULT YET. ADD YOUR CLOUDFLARE WORKER URL IN <code>config.js</code> TO TURN ON AUTOMATIC VERIFIED LOOKUPS.';return}$('#lookupResult').innerHTML='<div class="lookup-loading">✨ CHECKING YOUR SECURE NUTRITION ENDPOINT…</div>';try{const u=new URL(endpoint,location.href);u.searchParams.set('restaurant',rn);u.searchParams.set('item',item);const r=await fetch(u,{headers:{Accept:'application/json'}});let payload={};try{payload=await r.json()}catch{}if(!r.ok)throw new Error(payload?.message||`LOOKUP FAILED (${r.status})`);const clean=cleanRestaurantNutrition(payload,rn,item);if(!clean)throw new Error('THE ENDPOINT RESPONSE DID NOT INCLUDE ALL REQUIRED NUTRITION FIELDS');renderRestaurantLookup(clean,{canSave:true})}catch(e){$('#lookupResult').innerHTML=`<div class="lookup-error">⚠️ ${esc(e.message||'THE VERIFIED ENDPOINT DID NOT RETURN USABLE NUTRITION.')}<br><small>YOUR BUILT-IN + PERSONAL VAULTS ARE STILL WORKING. NOTHING WAS INVENTED.</small></div>`}}
function initBattle(){const o=allRecipes().map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');$('#battleA').innerHTML=o;$('#battleB').innerHTML=o;$('#battleB').selectedIndex=Math.min(10,$('#battleB').options.length-1);$$('[data-battle-mode]').forEach(b=>b.onclick=()=>{battleMode=b.dataset.battleMode;$$('[data-battle-mode]').forEach(x=>x.classList.toggle('active',x.dataset.battleMode===battleMode));battlePreview()});$('#battleA').onchange=battlePreview;$('#battleB').onchange=battlePreview;$('#battleLaunch').onclick=()=>{battlePreview(true);toast('BATTLE COMPLETE 🏆')};battlePreview()}
function battleValue(n){if(battleMode==='protein')return n.protein;if(battleMode==='fiber')return n.fiber;if(battleMode==='calories')return -n.calories;return (n.protein+n.fiber)/Math.max(1,n.calories)*100}
function initBattleBars(a,b,na,nb){const maxC=Math.max(na.calories,nb.calories,1),maxP=Math.max(na.protein,nb.protein,1),maxF=Math.max(na.fiber,nb.fiber,1);$('#battleBars').innerHTML=`${bar(a.name+' · CAL',na.calories,maxC,'')} ${bar(b.name+' · CAL',nb.calories,maxC,'')} ${bar(a.name+' · PROTEIN',na.protein,maxP,'G')} ${bar(b.name+' · PROTEIN',nb.protein,maxP,'G')} ${bar(a.name+' · FIBER',na.fiber,maxF,'G')} ${bar(b.name+' · FIBER',nb.fiber,maxF,'G')}`}
function battlePreview(animate=false){const a=allRecipes().find(r=>r.id===$('#battleA').value),b=allRecipes().find(r=>r.id===$('#battleB').value);if(!a||!b)return;const na=autoNutrition(a),nb=autoNutrition(b),va=battleValue(na),vb=battleValue(nb),win=va===vb?null:va>vb?a:b;const rule={protein:'HIGHER PROTEIN',fiber:'HIGHER FIBER',calories:'LOWER CALORIES',density:'HIGHER (PROTEIN + FIBER) PER 100 KCAL'}[battleMode];$('#battleArena').innerHTML=`<article class="fighter"><img src="${recipeImage(a)}" alt="${esc(a.name)}"><h3>${esc(a.name)}</h3><p>${na.calories} KCAL · ${Math.round(na.protein)}G P · ${Math.round(na.fiber)}G FIBER</p></article><div class="winner-badge"><strong>${win?'🏆':'🤝'}</strong><span>${win?esc(win.name)+' WINS':'TIE'}<br>RULE: ${rule}</span></div><article class="fighter"><img src="${recipeImage(b)}" alt="${esc(b.name)}"><h3>${esc(b.name)}</h3><p>${nb.calories} KCAL · ${Math.round(nb.protein)}G P · ${Math.round(nb.fiber)}G FIBER</p></article>`;initBattleBars(a,b,na,nb)}
function cartEntries(){
  const merged=new Map();
  (Array.isArray(state.cart)?state.cart:[]).forEach(entry=>{
    const id=typeof entry==='string'?entry:entry?.id;
    const qty=typeof entry==='string'?1:Math.max(1,Math.min(99,Math.round(+entry?.qty||1)));
    if(id&&SHOP_PRODUCTS.some(p=>p.id===id))merged.set(id,(merged.get(id)||0)+qty);
  });
  state.cart=[...merged].map(([id,qty])=>({id,qty}));
  return state.cart;
}
function cartQuantity(){return cartEntries().reduce((n,x)=>n+x.qty,0)}
function addCart(id,qty=1){qty=Math.max(1,Math.min(99,Math.round(+qty||1)));const items=cartEntries(),hit=items.find(x=>x.id===id);if(hit)hit.qty=Math.min(99,hit.qty+qty);else items.push({id,qty});state.cart=items;save();shopCounts();renderRecommendations();toast(`ADDED ${qty} TO CART 🛍️`)}
function setCartQty(id,qty){const items=cartEntries(),hit=items.find(x=>x.id===id);if(!hit)return;hit.qty=Math.max(1,Math.min(99,Math.round(+qty||1)));state.cart=items;save();shopCounts()}
function removeCartItem(id){state.cart=cartEntries().filter(x=>x.id!==id);save();shopCounts()}
function initShop(){
  const cats=[...new Set(SHOP_PRODUCTS.map(p=>p.category))].sort();
  $('#shopCategory').innerHTML='<option value="all">ALL DESIGN WORLDS</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');
  $('#designCount') && ($('#designCount').textContent=SHOP_PRODUCTS.length);
  $('#shopSearch').oninput=()=>renderShop();$('#shopCategory').onchange=()=>renderShop();$('#shopSort').onchange=()=>renderShop();
  $('#openCart').onclick=openCart;
  $('#showWishlist').onclick=()=>{$('#shopSearch').value='';renderShop('wishlist')};
  $('#showSaved').onclick=()=>{$('#shopSearch').value='';renderShop('saved')};
  cartEntries();renderShop();renderRecommendations();
}
function renderShop(mode='all'){
  const q=$('#shopSearch').value.toLowerCase().trim(),c=$('#shopCategory').value,sort=$('#shopSort').value;
  let a=SHOP_PRODUCTS.filter(p=>(c==='all'||p.category===c)&&((p.name+' '+p.category+' '+p.series+' '+p.tags).toLowerCase().includes(q)));
  if(mode==='wishlist')a=a.filter(p=>state.wishlist.includes(p.id));
  if(mode==='saved')a=a.filter(p=>state.saved.includes(p.id));
  if(sort==='price-low')a.sort((x,y)=>x.price-y.price);else if(sort==='price-high')a.sort((x,y)=>y.price-x.price);else if(sort==='name')a.sort((x,y)=>x.name.localeCompare(y.name));else a.sort((x,y)=>(y.featured||0)-(x.featured||0));
  $('#shopGrid').innerHTML=a.map(p=>`<article class="shop-card" data-product-card="${p.id}"><button class="shop-image-button" data-quick="${p.id}" aria-label="View ${esc(p.name)} details"><img loading="lazy" decoding="async" src="${shopImage(p)}" alt="${esc(p.name)} design work"></button><div class="card-body"><div class="shop-meta-line"><span class="mini-kicker">${esc(p.category)}</span><span class="archive-pill">${p.image?'ORIGINAL IMAGE':'ARCHIVE RECORD'}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.desc||'Berry Vibes Studio design work recovered from earlier chats.')}</p><div class="price-row"><strong>$${p.price.toFixed(2)}</strong><span>DIGITAL / CONCEPT</span></div><div class="quantity-row"><span>QUANTITY</span><div class="quantity-stepper"><button type="button" data-qty-minus="${p.id}" aria-label="Decrease quantity">−</button><b data-qty-value="${p.id}">1</b><button type="button" data-qty-plus="${p.id}" aria-label="Increase quantity">+</button></div></div><div class="shop-actions"><button data-cart="${p.id}">ADD TO CART</button><button data-quick="${p.id}">DETAILS</button><button data-wish="${p.id}" title="Wishlist">${state.wishlist.includes(p.id)?'♥':'♡'}</button><button data-save="${p.id}" title="Save">${state.saved.includes(p.id)?'🔖':'📑'}</button></div></div></article>`).join('')||'<div class="empty">NO DESIGN ITEMS MATCH THIS VIEW.</div>';
  $$('[data-qty-minus]').forEach(b=>b.onclick=()=>{const v=$(`[data-qty-value="${b.dataset.qtyMinus}"]`);v.textContent=Math.max(1,(+v.textContent||1)-1)});
  $$('[data-qty-plus]').forEach(b=>b.onclick=()=>{const v=$(`[data-qty-value="${b.dataset.qtyPlus}"]`);v.textContent=Math.min(99,(+v.textContent||1)+1)});
  $$('[data-cart]').forEach(b=>b.onclick=()=>{const v=$(`[data-qty-value="${b.dataset.cart}"]`);addCart(b.dataset.cart,+v?.textContent||1)});
  $$('[data-quick]').forEach(b=>b.onclick=()=>openProductDetails(b.dataset.quick));
  $$('[data-wish]').forEach(b=>b.onclick=()=>{toggleList(state.wishlist,b.dataset.wish);save();renderShop(mode);renderRecommendations();shopCounts()});
  $$('[data-save]').forEach(b=>b.onclick=()=>{toggleList(state.saved,b.dataset.save);save();renderShop(mode);renderRecommendations();shopCounts()});
  shopCounts();
}
function toggleList(a,id){const i=a.indexOf(id);i>=0?a.splice(i,1):a.push(id)}
function shopCounts(){if($('#cartCount'))$('#cartCount').textContent=cartQuantity();if($('#wishlistCount'))$('#wishlistCount').textContent=state.wishlist.length;if($('#savedCount'))$('#savedCount').textContent=state.saved.length}
function recommendationProducts(){
  const engaged=[...cartEntries().map(x=>x.id),...state.wishlist,...state.saved];
  const cats=engaged.map(id=>SHOP_PRODUCTS.find(p=>p.id===id)?.category).filter(Boolean);
  const series=engaged.map(id=>SHOP_PRODUCTS.find(p=>p.id===id)?.series).filter(Boolean);
  return SHOP_PRODUCTS.filter(p=>!engaged.includes(p.id)).map(p=>({p,score:(cats.includes(p.category)?4:0)+(series.includes(p.series)?6:0)+(p.featured||0)/100})).sort((a,b)=>b.score-a.score).slice(0,6).map(x=>x.p);
}
function renderRecommendations(){const box=$('#shopRecommendations');if(!box)return;const a=recommendationProducts();box.innerHTML=a.map(p=>`<article class="recommend-card"><img loading="lazy" decoding="async" src="${shopImage(p)}" alt="${esc(p.name)}"><div><span>${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>$${p.price.toFixed(2)}</p><button class="ghost-button" data-rec-cart="${p.id}">ADD 1 TO CART</button></div></article>`).join('');$$('[data-rec-cart]').forEach(b=>b.onclick=()=>addCart(b.dataset.recCart,1))}
function openProductDetails(id){const p=SHOP_PRODUCTS.find(x=>x.id===id),d=$('#cartDialog');if(!p||!d)return;const related=SHOP_PRODUCTS.filter(x=>x.id!==p.id&&(x.series===p.series||x.category===p.category)).slice(0,4);$('#cartDialogBody').innerHTML=`<div class="dialog-inner product-detail"><button class="dialog-x" data-close-dialog>×</button><div class="dialog-hero"><img loading="lazy" decoding="async" src="${shopImage(p)}" alt="${esc(p.name)}"><div><span class="mini-kicker">${esc(p.category)} · ${p.image?'ORIGINAL STANDALONE ART':'PAST-CHAT ARCHIVE RECORD'}</span><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><div class="price-row"><strong>$${p.price.toFixed(2)}</strong><span>DIGITAL / CONCEPT</span></div><div class="quantity-row"><span>QUANTITY</span><div class="quantity-stepper"><button id="detailMinus">−</button><b id="detailQty">1</b><button id="detailPlus">+</button></div></div><button class="primary-button wide" id="detailAdd">ADD TO CART 🛍️</button></div></div>${related.length?`<div class="detail-related"><span class="mini-kicker">MORE FROM THIS WORLD</span><div>${related.map(x=>`<button data-related="${x.id}"><img src="${shopImage(x)}" alt=""><b>${esc(x.name)}</b></button>`).join('')}</div></div>`:''}</div>`;$('#detailMinus').onclick=()=>$('#detailQty').textContent=Math.max(1,(+$('#detailQty').textContent||1)-1);$('#detailPlus').onclick=()=>$('#detailQty').textContent=Math.min(99,(+$('#detailQty').textContent||1)+1);$('#detailAdd').onclick=()=>addCart(p.id,+$('#detailQty').textContent||1);$$('[data-close-dialog]',d).forEach(x=>x.onclick=()=>d.close());$$('[data-related]').forEach(b=>b.onclick=()=>openProductDetails(b.dataset.related));if(!d.open)d.showModal()}
function openCart(){
  const d=$('#cartDialog'),entries=cartEntries(),items=entries.map(e=>({entry:e,p:SHOP_PRODUCTS.find(p=>p.id===e.id)})).filter(x=>x.p),total=items.reduce((a,x)=>a+x.p.price*x.entry.qty,0);
  $('#cartDialogBody').innerHTML=`<div class="dialog-inner"><button class="dialog-x" data-close-dialog>×</button><span class="mini-kicker">BERRY CART</span><h2>YOUR CART</h2><div class="cart-list">${items.length?items.map(({p,entry})=>`<div class="cart-item"><img src="${shopImage(p)}" alt=""><div class="cart-item-copy"><b>${esc(p.name)}</b><small>$${p.price.toFixed(2)} EACH</small><div class="quantity-stepper cart-stepper"><button data-cart-minus="${p.id}">−</button><b>${entry.qty}</b><button data-cart-plus="${p.id}">+</button></div></div><strong>$${(p.price*entry.qty).toFixed(2)}</strong><button class="ghost-button" data-remove-cart="${p.id}">REMOVE</button></div>`).join(''):'<div class="empty">YOUR CART IS EMPTY.</div>'}</div><div class="cart-total"><b>TOTAL · ${cartQuantity()} ITEM${cartQuantity()===1?'':'S'}</b><strong>$${total.toFixed(2)}</strong></div><button class="primary-button wide" id="checkoutPreview" ${items.length?'':'disabled'}>PROCEED TO CHECKOUT PREVIEW ✦</button><p class="auth-note">CHECKOUT PREVIEW ONLY. CONNECT A HOSTED PAYMENT FLOW FOR REAL SALES.</p></div>`;
  $$('[data-cart-minus]').forEach(b=>b.onclick=()=>{const e=cartEntries().find(x=>x.id===b.dataset.cartMinus);if(e){e.qty>1?setCartQty(e.id,e.qty-1):removeCartItem(e.id);openCart();renderRecommendations()}});
  $$('[data-cart-plus]').forEach(b=>b.onclick=()=>{const e=cartEntries().find(x=>x.id===b.dataset.cartPlus);if(e){setCartQty(e.id,e.qty+1);openCart();renderRecommendations()}});
  $$('[data-remove-cart]').forEach(b=>b.onclick=()=>{removeCartItem(b.dataset.removeCart);openCart();renderRecommendations()});
  $$('[data-close-dialog]',d).forEach(x=>x.onclick=()=>d.close());const co=$('#checkoutPreview');if(co)co.onclick=()=>{location.href='checkout.html'};if(!d.open)d.showModal();
}
function initCheckout(){const entries=cartEntries(),items=entries.map(e=>({entry:e,p:SHOP_PRODUCTS.find(p=>p.id===e.id)})).filter(x=>x.p),subtotal=items.reduce((a,x)=>a+x.p.price*x.entry.qty,0);const box=$('#checkoutItems'),tot=$('#checkoutTotals');if(box)box.innerHTML=items.length?items.map(({p,entry})=>`<article class="checkout-item"><img src="${shopImage(p)}" alt="${esc(p.name)}"><div><span>${esc(p.category)}</span><h3>${esc(p.name)}</h3><small>QTY ${entry.qty} · $${p.price.toFixed(2)} EACH</small></div><strong>$${(p.price*entry.qty).toFixed(2)}</strong></article>`).join(''):'<div class="empty">YOUR CART IS EMPTY. <a href="shop.html"><b>GO PICK SOME ART ✦</b></a></div>';if(tot)tot.innerHTML=`<div><span>ITEMS</span><b>${cartQuantity()}</b></div><div><span>SUBTOTAL</span><b>$${subtotal.toFixed(2)}</b></div><div class="grand"><span>PREVIEW TOTAL</span><strong>$${subtotal.toFixed(2)}</strong></div>`;const f=$('#checkoutForm');if(f)f.onsubmit=e=>{e.preventDefault();if(!items.length)return toast('YOUR CART IS EMPTY');const name=$('#checkoutName').value.trim(),email=$('#checkoutEmail').value.trim();if(!name||!email)return toast('ADD YOUR NAME + EMAIL');const order='BV-'+Date.now().toString(36).toUpperCase();state.cart=[];save();const c=$('#orderConfirmation');c.hidden=false;c.innerHTML=`<b>ORDER PREVIEW CREATED ✦</b><strong>${order}</strong><p>${esc(name)}, your local preview for ${items.length} design selection${items.length===1?'':'s'} is ready. No payment was collected.</p><a class="primary-button" href="shop.html">BACK TO SHOP</a>`;f.hidden=true;shopCounts();if(box)box.innerHTML='<div class="empty">PREVIEW ORDER CREATED ✨</div>';if(tot)tot.innerHTML='';toast('LOCAL ORDER PREVIEW CREATED ✦')}}
function initKineticInteractions(){const board=$('#orbitBoard'),orb=$('#draggableBerry');if(board&&orb){let drag=false,ox=0,oy=0;const move=e=>{if(!drag)return;const r=board.getBoundingClientRect();let x=e.clientX-r.left-ox,y=e.clientY-r.top-oy;x=Math.max(0,Math.min(r.width-orb.offsetWidth,x));y=Math.max(0,Math.min(r.height-orb.offsetHeight,y));orb.style.left=x+'px';orb.style.top=y+'px';orb.style.transform='rotate('+(x/r.width*18-9)+'deg) scale(1.04)'};orb.addEventListener('pointerdown',e=>{drag=true;orb.setPointerCapture(e.pointerId);const r=orb.getBoundingClientRect();ox=e.clientX-r.left;oy=e.clientY-r.top;orb.classList.add('dragging')});orb.addEventListener('pointermove',move);orb.addEventListener('pointerup',e=>{drag=false;orb.releasePointerCapture?.(e.pointerId);orb.classList.remove('dragging');orb.style.transform=''});orb.addEventListener('pointercancel',()=>{drag=false;orb.classList.remove('dragging')})}document.addEventListener('click',e=>{if(e.target.closest('button,a,input,select,textarea,dialog'))return;const s=document.createElement('i');s.className='click-spark';s.textContent=['✦','✧','•','♡'][Math.floor(Math.random()*4)];s.style.left=e.clientX+'px';s.style.top=e.clientY+'px';document.body.appendChild(s);setTimeout(()=>s.remove(),650)});if(matchMedia('(pointer:fine)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches){$$('.primary-button,.ghost-button,.wide-button,.choice-grid a').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();const x=(e.clientX-r.left-r.width/2)*.06,y=(e.clientY-r.top-r.height/2)*.08;el.style.translate=x+'px '+y+'px'});el.addEventListener('pointerleave',()=>el.style.translate='0 0')})}}
function initFacts(){groupsTo($('#factGroup'),allRecipes());function render(){const q=$('#factSearch').value.toLowerCase(),g=$('#factGroup').value,a=allRecipes().filter(r=>(g==='all'||r.group===g)&&((r.name+' '+r.group).toLowerCase().includes(q)));$('#factGrid').innerHTML=a.slice(0,factVisible).map(r=>`<article class="fact-card"><span class="mini-kicker">${esc(r.group)}</span><h3>${esc(r.name)}</h3>${recipeFacts(r).map(x=>`<div class="fact-stack"><div>${esc(x)}</div></div>`).join('')}</article>`).join('');$('#loadMoreFacts').hidden=factVisible>=a.length}$('#factSearch').oninput=()=>{factVisible=18;render()};$('#factGroup').onchange=()=>{factVisible=18;render()};$('#loadMoreFacts').onclick=()=>{factVisible+=18;render()};render();$('#exerciseFacts').innerHTML=MOVEMENTS.map(m=>`<article class="movement-card"><span>${m.emoji}</span><h3>${m.name}</h3><p>${m.copy}</p><p>⏱️ PRESET DURATION BUTTONS · NO TYPING.</p><p>✨ AUTO CLICK-TIME LOGGING.</p></article>`).join('')}
function initProfile(){const p=state.profile;$('#profileName').value=p.name||'';$('#profileHeight').value=p.height||'';$('#profileWeight').value=p.weight||'';$('#profileReason').value=p.reason||'';$('#accentColor').value=p.accent||'#6e46ff';function photo(){const el=$('#profilePreview');if(p.photo){el.style.backgroundImage=`url(${p.photo})`;el.textContent=''}else{el.style.backgroundImage='';el.textContent='🍓'}$('#profileMini').textContent=(p.name||'BERRY PROFILE').toUpperCase()}photo();$('#profilePic').onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2_500_000)return toast('USE AN IMAGE UNDER 2.5 MB FOR LOCAL STORAGE');const r=new FileReader();r.onload=()=>{p.photo=r.result;save();photo();toast('PROFILE PIC SAVED ✦')};r.readAsDataURL(f)};$('#profileForm').onsubmit=e=>{e.preventDefault();p.name=$('#profileName').value.trim();p.height=$('#profileHeight').value.trim();p.weight=+$('#profileWeight').value||118;p.reason=$('#profileReason').value.trim();save();toast('PROFILE SAVED 👤')};$('#themeGrid').innerHTML=THEMES.map(t=>`<button class="theme-choice ${p.theme===t[0]?'active':''}" data-theme="${t[0]}" style="background:linear-gradient(135deg,${t[1]},${t[2]})"><b>${t[0].toUpperCase()}</b></button>`).join('');$$('[data-theme]').forEach(b=>b.onclick=()=>{p.theme=b.dataset.theme;save();applyTheme();$$('[data-theme]').forEach(x=>x.classList.toggle('active',x.dataset.theme===p.theme))});$('#accentColor').oninput=e=>{p.accent=e.target.value;save();applyTheme()};$('#resetTheme').onclick=()=>{p.theme='berry';p.accent='#6e46ff';$('#accentColor').value=p.accent;save();applyTheme();initProfile()}}

function init(){if(document.body.dataset.page==='login'){initLogin();return}if(!requireAuth())return;state=loadState();applyTheme();common();const p=document.body.dataset.page;({index:initDashboard,foods:initFoods,recipes:initRecipes,movement:initMovement,fasting:initFasting,restaurants:initRestaurants,battle:initBattle,shop:initShop,checkout:initCheckout,facts:initFacts,profile:initProfile}[p]||(()=>{}))()}
